package net.officefloor.hq.app.people;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.JoinTable;
import jakarta.persistence.ManyToMany;
import jakarta.persistence.Table;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person on the list: a name and whole-number "alpha", "beta" and "gamma" (each absent until
 * given), a second raw axis of whole-number "delta" and "epsilon" (each absent until given) with the derived "force"
 * (delta × epsilon), a whole-number "zeta" (absent until given) with the derived "sway"
 * (zeta − delta) and "torque" (force + 3 × sway), each absent while any of delta, epsilon or zeta is, "blend" (momentum + torque, absent while either is), "flux" (the average of the patrons' force, rounded down, zero without patrons), "crest" (blend + flux, absent while either is), "swing" (the positive torque of the people followed added together, zero without any), "haul" (crest + swing, absent while either is), "vector" (the average of the patrons' blend, rounded down, zero without patrons), and the derived "thrust" (alpha × beta), "drift" (gamma − alpha) and "momentum"
 * (thrust + 3 × drift), which are absent until all three raw values are given. A person may have
 * any number of "patrons": other people on the list, whose thrust added together is the person's
 * "backing". A person belongs to one sheet (null for the unnamed sheet) and is numbered within it, so sheets never share people. "Net" is momentum plus backing (backing counted as zero without patrons). A person may have a
 * "grade" (LOW, MID or HIGH; absent until given), from which their "weight" is 1, 3 or 5. "Load" is momentum times weight.
 * A person may have a "kind" (A, B or C; absent until given), from which their "verge" is 2, 3 or 5.
 * "Pivot" is torque times verge, absent while either is. "Yield" is pivot plus two times lift, absent while either is. "Grip" is yield minus coil, absent while either is. "Charge" is vector plus yield, absent while either is. "Churn" is tide minus vector, absent while either is. "Flow" is yield plus charge, absent while either is.
 * A person may have an "onset" date (absent until given); their "age" is the complete weeks from onset to the sheet's anchor.
 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. "Clout" is the average of the
 * patrons' effective, rounded down (zero without patrons). "Influence" is effective plus clout. "Brace" is influence plus two times force. "Tide" is the brace of the people followed added together, each followed brace taken as their momentum plus two times force and only positive braces counted (zero without any). "Strain" is crest minus brace. "Pulse" classifies strain against a tolerance band of 10 either side of zero.
 * A person may belong to any number of "regions": short codes typed in, like N1 or S2. A region's
 * "multiplier" comes from its first letter: N is 2, S is 3, any other is 1. "Reach" is the sum, over the
 * person's regions, of momentum times that region's multiplier. "Gust" is reach plus two times torque. "Coil" is gust minus momentum. A person may follow any number of other people on
 * the list, without being followed back; their "allies" are the people they follow. "Synergy" is the
 * allies' thrust added together (zero without allies). "Combined" is influence plus synergy.
 * A person may have a whole-number "score" (absent until given); their "note sum" is the score (zero
 * without one) and their "quality" is the score (absent without one). A person has a workflow "state",
 * starting at DRAFT and moved forward to REVIEW and then FINAL; a FINAL person may be reopened to REWORK
 * and moved forward to FINAL again. A person may be in any number of named "groups" of the sheet (none until put in one); where "their group"
 * is needed, it is the one whose name comes first alphabetically. */
@Entity
@Table(name = "person")
public class Person {

    /** The longest region code that can be stored. */
    public static final int REGION_MAX_LENGTH = 16;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The person's id within their sheet; the id the user and the API see. */
    @Column(name = "local_id")
    private Long localId;

    private String name;

    private Integer alpha;

    private Integer beta;

    private Integer gamma;

    private Integer delta;

    private Integer epsilon;

    private Integer zeta;

    @Enumerated(EnumType.STRING)
    private Grade grade;

    @Enumerated(EnumType.STRING)
    private Kind kind;

    private LocalDate onset;

    private boolean active = true;

    @Enumerated(EnumType.STRING)
    private State state = State.DRAFT;

    /** The id of the sheet the person belongs to; null for the unnamed sheet. */
    @Column(name = "sheet_id")
    private String sheetId;

    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"),
            inverseJoinColumns = @JoinColumn(name = "patron_id"))
    private Set<Person> patrons = new HashSet<>();

    /** The people this person follows: their allies. Following is one-directional. */
    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_follow", joinColumns = @JoinColumn(name = "follower_id"),
            inverseJoinColumns = @JoinColumn(name = "followed_id"))
    private Set<Person> follows = new HashSet<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_region", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "region")
    private Set<String> regions = new HashSet<>();

    private Integer score;

    /** The groups the person is in; none until put in one. */
    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_membership", joinColumns = @JoinColumn(name = "person_id"),
            inverseJoinColumns = @JoinColumn(name = "group_id"))
    private Set<PersonGroup> groups = new HashSet<>();

    protected Person() {
    }

    public Person(String sheetId, long localId, String name, Integer alpha, Integer beta, Integer gamma) {
        this.sheetId = sheetId;
        this.localId = localId;
        this.name = name;
        this.alpha = alpha;
        this.beta = beta;
        this.gamma = gamma;
    }

    public Long getId() {
        return id;
    }

    public Long getLocalId() {
        return localId;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public Integer getAlpha() {
        return alpha;
    }

    public void setAlpha(Integer alpha) {
        this.alpha = alpha;
    }

    public Integer getBeta() {
        return beta;
    }

    public void setBeta(Integer beta) {
        this.beta = beta;
    }

    public Integer getGamma() {
        return gamma;
    }

    public void setGamma(Integer gamma) {
        this.gamma = gamma;
    }

    public Integer getDelta() {
        return delta;
    }

    public void setDelta(Integer delta) {
        this.delta = delta;
    }

    public Integer getEpsilon() {
        return epsilon;
    }

    public void setEpsilon(Integer epsilon) {
        this.epsilon = epsilon;
    }

    public Integer getZeta() {
        return zeta;
    }

    public void setZeta(Integer zeta) {
        this.zeta = zeta;
    }

    public Grade getGrade() {
        return grade;
    }

    public void setGrade(Grade grade) {
        this.grade = grade;
    }

    public Kind getKind() {
        return kind;
    }

    public void setKind(Kind kind) {
        this.kind = kind;
    }

    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    public State getState() {
        return state;
    }

    public void setState(State state) {
        this.state = state;
    }

    /** The regions, sorted ascending. */
    public List<String> getRegions() {
        return regions.stream().sorted().toList();
    }

    public void setRegions(Collection<String> regions) {
        this.regions = new HashSet<>(regions);
    }

    /** The groups the person is in, sorted by name. */
    public List<PersonGroup> getGroups() {
        return groups.stream()
                .sorted(Comparator.comparing(PersonGroup::getName).thenComparing(PersonGroup::getLocalId))
                .toList();
    }

    public void setGroups(Collection<PersonGroup> groups) {
        this.groups = new HashSet<>(groups);
    }

    /** "Their group": the group whose name comes first alphabetically; absent when in none. */
    public PersonGroup getGroup() {
        return getGroups().stream().findFirst().orElse(null);
    }

    public Integer getScore() {
        return score;
    }

    public void setScore(Integer score) {
        this.score = score;
    }

    /** The note sum is the score; zero without one. */
    public int getNoteSum() {
        return score == null ? 0 : score;
    }

    /** Quality is the score; absent without one. */
    public Integer getQuality() {
        return score;
    }

    /** Adjusted is combined plus quality (quality counted as zero without a score); absent while combined is. */
    public Integer getAdjusted() {
        Integer combined = getCombined();
        Integer quality = getQuality();
        return combined == null ? null : combined + (quality == null ? 0 : quality);
    }

    public LocalDate getOnset() {
        return onset;
    }

    /** Age is the complete seven-day weeks from onset to the anchor (leftover days dropped), negative when onset is
     * after it and truncated toward zero; absent without an onset. */
    public Long getAge(LocalDate anchor) {
        return onset == null ? null : ChronoUnit.WEEKS.between(onset, anchor);
    }

    /** Decay is momentum minus age; absent while either is absent. */
    public Long getDecay(LocalDate anchor) {
        Integer momentum = getMomentum();
        Long age = getAge(anchor);
        return momentum == null || age == null ? null : momentum - age;
    }

    /** Weight comes from the grade: LOW 1, MID 3, HIGH 5; absent without a grade. */
    public Integer getWeight() {
        return grade == null ? null : grade.weight();
    }

    /** Verge comes from the kind: A 2, B 3, C 5; absent without a kind. */
    public Integer getVerge() {
        return kind == null ? null : kind.verge();
    }

    /** The patrons, sorted by name. */
    public List<Person> getPatrons() {
        return patrons.stream()
                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
                .toList();
    }

    public void setPatrons(Set<Person> patrons) {
        this.patrons = new HashSet<>(patrons);
    }

    /** The allies: the people this person follows, sorted by name. */
    public List<Person> getAllies() {
        return follows.stream()
                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
                .toList();
    }

    /** Replaces the people this person follows; whether they follow this person back is unchanged. */
    public void setAllies(Set<Person> allies) {
        this.follows = new HashSet<>(allies);
    }

    /** The derived values exist only once alpha, beta and gamma are all given. */
    private boolean complete() {
        return alpha != null && beta != null && gamma != null;
    }

    /** Thrust is alpha multiplied by beta; absent until alpha, beta and gamma are all given. */
    public Integer getThrust() {
        return complete() ? alpha * beta : null;
    }

    /** Drift is gamma minus alpha; absent until alpha, beta and gamma are all given. */
    public Integer getDrift() {
        return complete() ? gamma - alpha : null;
    }

    /** Momentum is thrust plus three times drift; absent while either is absent. */
    public Integer getMomentum() {
        Integer thrust = getThrust();
        Integer drift = getDrift();
        return thrust == null || drift == null ? null : thrust + 3 * drift;
    }

    /** Whether all of delta, epsilon and zeta are given; the concepts built on them are absent until they are. */
    private boolean hasSecondAxis() {
        return delta != null && epsilon != null && zeta != null;
    }

    /** Force is delta multiplied by epsilon; absent while any of delta, epsilon or zeta is absent. */
    public Integer getForce() {
        return hasSecondAxis() ? delta * epsilon : null;
    }

    /** Sway is zeta minus delta; absent while any of delta, epsilon or zeta is absent. */
    public Integer getSway() {
        return hasSecondAxis() ? zeta - delta : null;
    }

    /** Torque is force plus three times sway; absent while either is absent. */
    public Integer getTorque() {
        Integer force = getForce();
        Integer sway = getSway();
        return force == null || sway == null ? null : force + 3 * sway;
    }

    /** Pivot is torque times verge; absent while either is absent. */
    public Integer getPivot() {
        Integer torque = getTorque();
        Integer verge = getVerge();
        return torque == null || verge == null ? null : torque * verge;
    }

    /** Blend is momentum plus torque; absent while either is absent. */
    public Integer getBlend() {
        Integer momentum = getMomentum();
        Integer torque = getTorque();
        return momentum == null || torque == null ? null : momentum + torque;
    }

    /** Load is momentum times weight; absent while either is absent. */
    public Integer getLoad() {
        Integer momentum = getMomentum();
        Integer weight = getWeight();
        return momentum == null || weight == null ? null : momentum * weight;
    }

    /** A region's multiplier from its first letter: N is 2, S is 3, any other is 1. */
    static int regionMultiplier(String region) {
        return switch (region.isEmpty() ? ' ' : Character.toUpperCase(region.charAt(0))) {
            case 'N' -> 2;
            case 'S' -> 3;
            default -> 1;
        };
    }

    /** Reach is the sum over the regions of momentum times the region's multiplier; absent without momentum or regions. */
    public Integer getReach() {
        Integer momentum = getMomentum();
        if (momentum == null || regions.isEmpty()) {
            return null;
        }
        return regions.stream().mapToInt(r -> momentum * regionMultiplier(r)).sum();
    }

    /** Backing is the sum of the patrons' thrust; absent without patrons or while any patron's thrust is absent. */
    public Integer getBacking() {
        if (patrons.isEmpty()) {
            return null;
        }
        int sum = 0;
        for (Person patron : patrons) {
            Integer thrust = patron.getThrust();
            if (thrust == null) {
                return null;
            }
            sum += thrust;
        }
        return sum;
    }

    /** Flux is the average of the patrons' force, rounded down; zero without patrons, absent while any patron's force is absent. */
    public Integer getFlux() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer force = patron.getForce();
            if (force == null) {
                return null;
            }
            sum += force;
        }
        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
    }

    /** Crest is blend plus flux; absent while either is absent. */
    public Integer getCrest() {
        Integer blend = getBlend();
        Integer flux = getFlux();
        return blend == null || flux == null ? null : blend + flux;
    }

    /** Swing is the sum of the positive torque of the people followed (zero or below is dropped); zero without allies, absent while any ally's torque is absent. */
    public Integer getSwing() {
        int sum = 0;
        for (Person ally : getAllies()) {
            Integer torque = ally.getTorque();
            if (torque == null) {
                return null;
            }
            if (torque > 0) {
                sum += torque;
            }
        }
        return sum;
    }

    /** Vector is the average of the patrons' blend, rounded down; zero without patrons, absent while any patron's blend is absent. */
    public Integer getVector() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer blend = patron.getBlend();
            if (blend == null) {
                return null;
            }
            sum += blend;
        }
        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
    }

    /** Haul is crest plus swing; absent while either is absent. */
    public Integer getHaul() {
        Integer crest = getCrest();
        Integer swing = getSwing();
        return crest == null || swing == null ? null : crest + swing;
    }

    /** Synergy is the sum of the thrust of the people followed; zero without allies, absent while any ally's thrust is absent. */
    public Integer getSynergy() {
        int sum = 0;
        for (Person ally : getAllies()) {
            Integer thrust = ally.getThrust();
            if (thrust == null) {
                return null;
            }
            sum += thrust;
        }
        return sum;
    }

    /** Net is momentum plus backing, counting backing as zero without patrons; absent with momentum, or with a patron whose thrust is absent. */
    public Integer getNet() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        if (patrons.isEmpty()) {
            return momentum;
        }
        Integer backing = getBacking();
        return backing == null ? null : momentum + backing;
    }

    /** Effective is net while active, and half of net rounded down while not active (absent while net is). */
    public Integer getEffective() {
        Integer net = getNet();
        if (net == null || active) {
            return net;
        }
        return Math.floorDiv(net, 2);
    }

    /** Clout is the average of the patrons' effective, rounded down; zero without patrons, absent while any patron's effective is absent. */
    public Integer getClout() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer effective = patron.getEffective();
            if (effective == null) {
                return null;
            }
            sum += effective;
        }
        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
    }

    /** Influence is effective plus clout; absent while either is. */
    public Integer getInfluence() {
        Integer effective = getEffective();
        Integer clout = getClout();
        return effective == null || clout == null ? null : effective + clout;
    }

    /** Brace is influence plus two times force; absent while either is. */
    public Integer getBrace() {
        Integer influence = getInfluence();
        Integer force = getForce();
        return influence == null || force == null ? null : influence + 2 * force;
    }

    /**
     * Tide is the sum of the brace of the people followed, each taken as momentum plus two times force, counting only
     * positive braces; zero without allies, absent while any ally's momentum or force is absent.
     */
    public Integer getTide() {
        int sum = 0;
        for (Person ally : getAllies()) {
            Integer momentum = ally.getMomentum();
            Integer force = ally.getForce();
            if (momentum == null || force == null) {
                return null;
            }
            int brace = momentum + 2 * force;
            if (brace > 0) {
                sum += brace;
            }
        }
        return sum;
    }

    /** Strain is crest minus brace; absent while either is. */
    public Integer getStrain() {
        Integer crest = getCrest();
        Integer brace = getBrace();
        return crest == null || brace == null ? null : crest - brace;
    }

    /** Pulse classifies strain against a tolerance band: NEG below -10, FLAT within 10 of zero, POS above 10; absent with strain. */
    public String getPulse() {
        Integer strain = getStrain();
        if (strain == null) {
            return null;
        }
        return strain < -10 ? "NEG" : strain > 10 ? "POS" : "FLAT";
    }

    /** Combined is influence plus synergy; absent while either is. */
    public Integer getCombined() {
        Integer influence = getInfluence();
        Integer synergy = getSynergy();
        return influence == null || synergy == null ? null : influence + synergy;
    }

    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
    public String getTier() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
    }

    /** Phase classifies torque: EBB below zero, RUN up to 199, PEAK from 200; absent with torque. */
    public String getPhase() {
        Integer torque = getTorque();
        if (torque == null) {
            return null;
        }
        return torque < 0 ? "EBB" : torque <= 199 ? "RUN" : "PEAK";
    }

    /** Drag classifies blend: L0 below zero, L1 up to 49, L2 up to 149, L3 from 150; absent with blend. */
    public String getDrag() {
        Integer blend = getBlend();
        if (blend == null) {
            return null;
        }
        return blend < 0 ? "L0" : blend <= 49 ? "L1" : blend <= 149 ? "L2" : "L3";
    }

    /** Lift is blend times the drag's multiplier: L0 0, L1 1, L2 2, L3 3; absent with blend. */
    public Integer getLift() {
        Integer blend = getBlend();
        if (blend == null) {
            return null;
        }
        int multiplier = switch (getDrag()) {
            case "L3" -> 3;
            case "L2" -> 2;
            case "L1" -> 1;
            default -> 0;
        };
        return blend * multiplier;
    }

    /** Yield is pivot plus two times lift; absent while either is absent. */
    public Integer getYield() {
        Integer pivot = getPivot();
        Integer lift = getLift();
        return pivot == null || lift == null ? null : pivot + 2 * lift;
    }

    /** Band classifies adjusted: E below 0, D up to 99, C up to 249, B up to 499, A from 500; absent with adjusted. */
    public String getBand() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        return adjusted < 0 ? "E" : adjusted <= 99 ? "D" : adjusted <= 249 ? "C" : adjusted <= 499 ? "B" : "A";
    }

    /** Scaled is adjusted times the band's multiplier: A 4, B 3, C 2, D 1, E 0; absent with adjusted. */
    public Integer getScaled() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        int multiplier = switch (getBand()) {
            case "A" -> 4;
            case "B" -> 3;
            case "C" -> 2;
            case "D" -> 1;
            default -> 0;
        };
        return adjusted * multiplier;
    }

    /** Thrum is scaled plus two times torque; absent while either is absent. */
    public Integer getThrum() {
        Integer scaled = getScaled();
        Integer torque = getTorque();
        return scaled == null || torque == null ? null : scaled + 2 * torque;
    }

    /** Spool is thrum minus blend; absent while either is absent. */
    public Integer getSpool() {
        Integer thrum = getThrum();
        Integer blend = getBlend();
        return thrum == null || blend == null ? null : thrum - blend;
    }

    /** Gust is reach plus two times torque; absent while either is absent. */
    public Integer getGust() {
        Integer reach = getReach();
        Integer torque = getTorque();
        return reach == null || torque == null ? null : reach + 2 * torque;
    }

    /** Coil is gust minus momentum; absent while either is absent. */
    public Integer getCoil() {
        Integer gust = getGust();
        Integer momentum = getMomentum();
        return gust == null || momentum == null ? null : gust - momentum;
    }

    /** Grip is yield minus coil; absent while either is absent. */
    public Integer getGrip() {
        Integer yield = getYield();
        Integer coil = getCoil();
        return yield == null || coil == null ? null : yield - coil;
    }

    /** Charge is vector plus yield; absent while either is absent. */
    public Integer getCharge() {
        Integer vector = getVector();
        Integer yield = getYield();
        return vector == null || yield == null ? null : vector + yield;
    }

    /** Churn is tide minus vector; absent while either is absent. */
    public Integer getChurn() {
        Integer tide = getTide();
        Integer vector = getVector();
        return tide == null || vector == null ? null : tide - vector;
    }

    /** Flow is yield plus charge; absent while either is absent. */
    public Integer getFlow() {
        Integer yield = getYield();
        Integer charge = getCharge();
        return yield == null || charge == null ? null : yield + charge;
    }
}
